/* Talk: conversation AX (speaker, choices, 0); returns the choice. */
static void demon5_Talk(uint16_t ax)
{
    svc_Talk(ax);
    return;
}

/* Say: one line, BX, said by AX (0: narration). */
static void demon5_Say(uint16_t ax, uint16_t bx)
{
    fv_talk_buf = ax;
    CS_W(0x24E5) = bx;
    demon5_Talk(talk_buf);
    return;
}

